package com.agacostays.billing.client;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import java.math.BigDecimal;
@Component public class PaymentServiceClient{private final RestClient c;public PaymentServiceClient(@Value("${service.payment.url}")String u,RestClient.Builder b){c=b.baseUrl(u).build();}public boolean initiateFinalBillPayment(Long billId,Long bookingId,Long customerId,BigDecimal amount,String paymentMethod){try{return c.post().uri("/api/billing/payments").body(new Payload(billId,bookingId,customerId,amount,paymentMethod)).retrieve().toBodilessEntity().getStatusCode().is2xxSuccessful();}catch(Exception e){return false;}}public record Payload(Long billId,Long bookingId,Long customerId,BigDecimal amount,String paymentMethod){}}
